rules.suggestion:
每个unsafe块必须用// SAFETY注释说明安全条件：
```rust
// 错误 - 无说明
unsafe {
    let ptr = data.as_ptr();
    *ptr.add(offset) = value;
}

// 正确 - 说明安全不变量
// SAFETY: offset 调用前已验证在 data.len() 范围内，
// data 不会在unsafe块期间被其他引用修改（独占借用保证）。
unsafe {
    let ptr = data.as_ptr();
    *ptr.add(offset) = value;
}
```

使用?传播错误或提供合理的默认值：
```rust
// 危险
let user = get_user(id).unwrap(); // panic!

// 正确 - 使用?传播错误
let user = get_user(id)?;

// 正确 - 使用match处理
let user = match get_user(id) {
    Ok(u) => u,
    Err(e) => {
        eprintln!("获取用户失败: {}", e);
        return;
    }
};

// 正确 - 使用unwrap_or提供默认值
let name = user.name().unwrap_or("Anonymous");

// 测试代码中可以使用unwrap
#[cfg(test)]
let user = get_user(id).unwrap();
```

优先使用引用和生命周期，减少不必要的clone：
```rust
// 低效 - 过度clone
fn process(data: Vec<String>) {
    let copy1 = data.clone(); // 不必要的深拷贝
    let copy2 = data.clone(); // 又一次深拷贝
}

// 高效 - 使用引用
fn process(data: &[String]) {
    let first = &data[0]; // 借用，零成本
    let second = &data[1];
}

// 必要时使用 Rc/Arc 共享所有权
use std::rc::Rc;
let shared = Rc::new(expensive_data);
let clone1 = Rc::clone(&shared); // 仅增加引用计数，不复制数据
```

使用chars()迭代器或get方法安全切片：
```rust
// 危险 - 可能panic
let s = "你好世界";
let slice = &s[0..3]; // panic! 3不在字符边界

// 安全方式1 - 使用get（返回Option）
let slice = s.get(0..3).unwrap_or("");

// 安全方式2 - 使用chars按字符操作
let first_two: String = s.chars().take(2).collect(); // "你好"

// 安全方式3 - 使用char_indices找到正确边界
let boundaries: Vec<usize> = s.char_indices().map(|(i, _)| i).collect();
```

明确标注生命周期，确保引用不超过数据存活期：
```rust
// 错误 - 返回的引用可能比输入生命周期更长
fn first_word(s: &String) -> &str {
    // 编译器可能推断错误
}

// 正确 - 明确标注
fn first_word<'a>(s: &'a String) -> &'a str {
    &s[..s.find(' ').unwrap_or(s.len())]
}

// 避免过度复杂的生命周期 - 考虑使用所有权
// 如果不需要共享数据，直接返回拥有所有权的类型
fn first_word(s: &str) -> String {
    s.split_whitespace().next().unwrap_or("").to_string()
}
```

为Trait对象添加Send+Sync约束：
```rust
// 编译错误 - 无法跨线程
trait Handler {
    fn handle(&self);
}
async fn run(handler: Box<dyn Handler>) { } // 编译失败

// 正确 - 添加线程安全约束
trait Handler: Send + Sync {
    fn handle(&self);
}
async fn run(handler: Box<dyn Handler>) { } // OK

// 异步上下文常见模式
fn spawn_task(handler: Box<dyn Handler + Send + 'static>) {
    tokio::spawn(async move {
        handler.handle();
    });
}
```

已知大小时使用Vec::with_capacity预分配：
```rust
// 低效 - 多次重新分配
let mut v = Vec::new();
for i in 0..10000 {
    v.push(compute(i)); // 多次扩容，每次分配+复制
}

// 高效 - 预分配
let mut v = Vec::with_capacity(10000);
for i in 0..10000 {
    v.push(compute(i)); // 一次分配
}

// 或使用collect时的size_hint
let v: Vec<_> = iter.collect(); // iter如果有准确size_hint则自动预分配
```

库代码使用?传播错误，应用代码顶层统一处理：
```rust
// 不推荐 - 库代码中expect
fn read_config(path: &str) -> Config {
    let content = std::fs::read_to_string(path)
        .expect("读取配置文件失败"); // panic
    toml::from_str(&content).expect("解析配置失败")
}

// 推荐 - 返回Result
fn read_config(path: &str) -> Result<Config, ConfigError> {
    let content = std::fs::read_to_string(path)
        .map_err(|e| ConfigError::Io(e))?;
    toml::from_str(&content)
        .map_err(|e| ConfigError::Parse(e))
}

// 仅在main或测试中可以使用expect
fn main() {
    let config = read_config("config.toml").expect("启动失败");
}
```
